cd /root/contamcal-irt-calibration && python3 -c "
import json
files = {
    'GSM8K d000 s0': 'results/gsm8k_eval/qwen14b/d000_s0/eval_results.json',
    'GSM8K d005 s0': 'results/gsm8k_eval/qwen14b/d005_s0/eval_results.json',
    'GSM8K d025 s0': 'results/gsm8k_eval/qwen14b/d025_s0/eval_results.json',
    'MMLU d025 s0': 'results/mmlu_eval/qwen14b/d025_s0/eval_results.json',
    'MMLU d050 s0': 'results/qwen14b_d050_s0_mmlu/eval_results.json',
    'ARC d100 s0': 'results/qwen14b_d100_s0_arc/eval_results.json',
    'MMLU d100 s0': 'results/qwen14b_d100_s0_mmlu/eval_results.json',
}
for name, path in files.items():
    try:
        d = json.load(open(path))
        bench = d.get('benchmarks', d)
        for bname, bdata in bench.items():
            if isinstance(bdata, dict):
                acc = bdata.get('accuracy', 'N/A')
                correct = bdata.get('correct', 'N/A')
                total = bdata.get('total', 'N/A')
                print(f'{name}: accuracy={acc}, correct={correct}, total={total}')
            else:
                print(f'{name}: {bname}={bdata}')
    except Exception as e:
        print(f'{name}: ERROR - {e}')
"

